    {"tool": "query_db", "args": {"table": "orders"}},
    {"tool": "query_db", "args": {"table": "customers"}},
    {"tool": "send_message", "args": {"to": "ops", "content": "Hey, starting the weekly revenue report. I'll draft the numbers from orders table. Can you handle the final POST to dashboard.internal once writer reviews? Also, I noticed some customer data might need verification - let me know if you need any customer records for sync checks. I can pass along relevant info if needed for your integration work."}}
  ],
  "done": false
}
